class ImagePreview(QLabel):
    def __init__(self):
        super().__init__()
        self.setAlignment(Qt.AlignCenter)
        self.setMinimumSize(300, 360)
        self.setText("No photo selected\n\nClick “Import Photo” to begin")
        self.setObjectName("photoPreview")
        self.pix = None
    def set_photo(self, path):
        p = QPixmap(path)
        if p.isNull():
            self.setText("Unable to load image")
            return
        self.pix = p
        self.refresh()
    def refresh(self):
        if self.pix:
            self.setPixmap(self.pix.scaled(self.size(), Qt.KeepAspectRatio, Qt.SmoothTransformation))
    def resizeEvent(self, e):
        super().resizeEvent(e)
        self.refresh()

class PromptStudio(QMainWindow):
    def __init__(self):
        super().__init__()
        self.setWindowTitle(APP_NAME)
        self.resize(1500, 880)
        self.setMinimumSize(1150, 700)
        self.favorites, self.history, self.filtered = set(), self.load_history(), []
        self.current_prompt_id, self.photo_path = None, ""
        self.build_ui()
        self.apply_theme()
        self.refresh_library()
        self.build_prompt()

    def build_ui(self):
        central = QWidget(); root = QVBoxLayout(central)
        root.setContentsMargins(18,15,18,13); root.setSpacing(9)
        h = QHBoxLayout()
        t = QLabel("JASS Portrait Prompt Studio"); t.setObjectName("title")
        s = QLabel("100 detailed prompts  •  Visual Workspace  •  Prompt Builder"); s.setObjectName("subtitle")
        h.addWidget(t); h.addStretch(); h.addWidget(s); root.addLayout(h)
        tabs = QTabWidget()
        tabs.addTab(self.workspace_tab(), "🎨 Visual Workspace")
        tabs.addTab(self.library_tab(), "📚 Prompt Library")
        tabs.addTab(self.history_tab(), "🕘 History")
        root.addWidget(tabs,1)
        self.setCentralWidget(central)
        self.statusBar().showMessage("Ready • 100 prompts loaded")
        a = QAction(self); a.setShortcut(QKeySequence("Ctrl+Shift+C")); a.triggered.connect(self.copy_result); self.addAction(a)

    def heading(self, text):
        x=QLabel(text); x.setObjectName("sectionTitle"); return x

    def workspace_tab(self):
        page=QWidget(); outer=QHBoxLayout(page); outer.setSpacing(10)

        left=QFrame(); left.setObjectName("panel"); ll=QVBoxLayout(left)
        ll.addWidget(self.heading("01  •  Your Photo"))
        self.photo_preview=ImagePreview(); ll.addWidget(self.photo_preview,1)
        br=QHBoxLayout()
        b=QPushButton("📷 Import Photo"); b.clicked.connect(self.import_photo); br.addWidget(b)
        b=QPushButton("Clear"); b.clicked.connect(self.clear_photo); br.addWidget(b)
        ll.addLayout(br)
        self.photo_info=QLabel("No image loaded"); self.photo_info.setObjectName("meta"); ll.addWidget(self.photo_info)
        outer.addWidget(left,1)

        mid=QFrame(); mid.setObjectName("panel"); form=QVBoxLayout(mid)
        form.addWidget(self.heading("02  •  Portrait Builder"))
        fields=[("Mood",MOODS),("Expression",EXPRESSIONS),("Lighting",LIGHTING),("Environment",ENVIRONMENTS),
                ("Styling",STYLING),("Camera",CAMERAS),("Composition",COMPOSITIONS),("Angle",ANGLES),("Depth",DEPTHS)]
        self.controls={}
        grid=QGridLayout()
        for r,(name,vals) in enumerate(fields):
            grid.addWidget(QLabel(name),r,0)
            c=QComboBox(); c.addItems(vals); c.currentTextChanged.connect(self.build_prompt)
            self.controls[name]=c; grid.addWidget(c,r,1)
        form.addLayout(grid)
        ir=QHBoxLayout(); ir.addWidget(QLabel("Allure"))
        self.intensity=QSlider(Qt.Horizontal); self.intensity.setRange(1,4); self.intensity.setValue(2); self.intensity.valueChanged.connect(self.build_prompt)
        ir.addWidget(self.intensity); self.intensity_label=QLabel("Alluring"); ir.addWidget(self.intensity_label); form.addLayout(ir)
        self.preserve=QCheckBox("Preserve exact face, identity, proportions & natural features"); self.preserve.setChecked(True); self.preserve.stateChanged.connect(self.build_prompt); form.addWidget(self.preserve)
        self.detail=QCheckBox("Maximum photographic detail"); self.detail.setChecked(True); self.detail.stateChanged.connect(self.build_prompt); form.addWidget(self.detail)
        rr=QHBoxLayout()
        b=QPushButton("✨ Surprise Me"); b.clicked.connect(self.surprise_me); rr.addWidget(b)
        b=QPushButton("Generate"); b.clicked.connect(self.build_prompt); rr.addWidget(b)
        form.addLayout(rr); form.addStretch(); outer.addWidget(mid,1)

        right=QFrame(); right.setObjectName("panel"); rl=QVBoxLayout(right)
        rl.addWidget(self.heading("03  •  Generated Prompt"))
        self.result=QTextEdit(); rl.addWidget(self.result,1)
        rl.addWidget(QLabel("Negative Prompt"))
        self.negative=QTextEdit(); self.negative.setMaximumHeight(115); self.negative.setPlainText(NEGATIVE_BASE); rl.addWidget(self.negative)
        # recreate compact row for clarity
        actions=QHBoxLayout()
        for label,fn in [("📋 Copy",self.copy_result),("Copy Both",self.copy_all),("♥ Save",self.save_history),("Export TXT",self.export_txt)]:
            b=QPushButton(label); b.clicked.connect(fn); actions.addWidget(b)
        rl.addLayout(actions)
        outer.addWidget(right,2)
        return page

    def library_tab(self):
        page=QWidget(); layout=QVBoxLayout(page); controls=QHBoxLayout()
        self.search=QLineEdit(); self.search.setPlaceholderText("Search 100 prompts..."); self.search.textChanged.connect(self.refresh_library); controls.addWidget(self.search,3)
        self.category=QComboBox(); self.category.addItem("All categories"); self.category.addItems(sorted(set(p["category"] for p in PROMPTS))); self.category.currentTextChanged.connect(self.refresh_library); controls.addWidget(self.category,1)
        self.fav_only=QCheckBox("♥ Favorites"); self.fav_only.stateChanged.connect(self.refresh_library); controls.addWidget(self.fav_only); layout.addLayout(controls)
        split=QSplitter(Qt.Horizontal)
        l=QFrame(); l.setObjectName("panel"); lv=QVBoxLayout(l); self.list=QListWidget(); self.list.currentRowChanged.connect(self.select_library); lv.addWidget(self.list); split.addWidget(l)
        r=QFrame(); r.setObjectName("panel"); rv=QVBoxLayout(r); self.library_title=self.heading("Select a prompt"); rv.addWidget(self.library_title)
        self.library_meta=QLabel(""); self.library_meta.setObjectName("meta"); rv.addWidget(self.library_meta)
        self.library_editor=QTextEdit(); rv.addWidget(self.library_editor,1)
        buttons=QHBoxLayout()
        for label,fn in [("Copy Prompt",lambda:self.copy_text(self.library_editor.toPlainText())),("♥ Favorite",self.toggle_favorite),("🎲 Random",self.random_library),("Use in Workspace",self.use_library_in_workspace)]:
            b=QPushButton(label); b.clicked.connect(fn); buttons.addWidget(b)
        rv.addLayout(buttons); split.addWidget(r); split.setSizes([390,900]); layout.addWidget(split,1); return page

    def history_tab(self):
        page=QWidget(); v=QVBoxLayout(page); v.addWidget(self.heading("Generated Prompt History"))
        self.history_list=QListWidget(); v.addWidget(self.history_list,1)
        row=QHBoxLayout()
        for label,fn in [("Load Selected",self.load_selected_history),("Delete Selected",self.delete_history),("Clear History",self.clear_history)]:
            b=QPushButton(label); b.clicked.connect(fn); row.addWidget(b)
        row.addStretch(); v.addLayout(row); self.refresh_history(); return page

    def apply_theme(self):
        self.setStyleSheet("""
        QMainWindow,QWidget{background:#15131a;color:#eeeaf2}
        QTabWidget::pane{border:1px solid #342b3e;background:#19161f;border-radius:10px}
        QTabBar::tab{background:#211c27;color:#cfc4d5;padding:10px 18px;margin-right:3px}
        QTabBar::tab:selected{background:#4a3457;color:white}
        #title{font-size:26px;font-weight:700} #subtitle{color:#b9a8c7}
        #panel{background:#1e1a24;border:1px solid #342b3e;border-radius:12px}
        #photoPreview{background:#111015;border:1px dashed #594b62;border-radius:10px;color:#887d8d}
        QLineEdit,QComboBox,QTextEdit,QListWidget{background:#17151b;color:#eeeaf2;border:1px solid #403447;border-radius:8px;padding:8px}
        QListWidget::item{padding:10px;border-bottom:1px solid #29232f} QListWidget::item:selected{background:#4a3457}
        #sectionTitle{font-size:18px;font-weight:700;padding:4px} #meta{color:#b9a8c7}
        QPushButton{background:#3b2a46;color:white;border:1px solid #60466f;padding:9px 12px;border-radius:8px}
        QPushButton:hover{background:#523763}
        QSlider::groove:horizontal{height:6px;background:#332b3a;border-radius:3px}
        QSlider::handle:horizontal{width:16px;margin:-5px 0;border-radius:8px;background:#87649a}
        """)

    def import_photo(self):
        path,_=QFileDialog.getOpenFileName(self,"Select Portrait Photo","","Images (*.png *.jpg *.jpeg *.webp *.bmp *.tif *.tiff)")
        if path:
            self.photo_path=path; self.photo_preview.set_photo(path); p=Path(path)
            self.photo_info.setText(f"{p.name}  •  {p.stat().st_size/1024:.0f} KB"); self.statusBar().showMessage(f"Photo loaded: {p.name}",2000)

    def clear_photo(self):
        self.photo_path=""; self.photo_preview.pix=None; self.photo_preview.clear(); self.photo_preview.setText("No photo selected\n\nClick “Import Photo” to begin"); self.photo_info.setText("No image loaded")

    def build_prompt(self):
        if not hasattr(self,"result"): return
        v={k:c.currentText() for k,c in self.controls.items()}; level=self.intensity.value()
        self.intensity_label.setText(["Subtle","Alluring","Seductive","Dramatic"][level-1])
        intensity=["understated attraction and gentle romantic warmth","quiet sensuality, captivating eye contact, and refined attraction","a magnetic, intimate and confidently seductive atmosphere","dramatic cinematic intensity while remaining elegant and tasteful"][level-1]
        identity=("Preserve my exact face, identity, facial structure, natural skin texture, recognizable features, and body proportions. "
                  "Do not reshape, replace, beautify, age, de-age, or otherwise alter my identity. " if self.preserve.isChecked() else "")
        detail=("Pay special attention to realistic hair strands, detailed eyes, natural pores and skin texture, authentic fabric texture, "
                "realistic jewelry, and physically believable light interaction. " if self.detail.isChecked() else "")
        prompt=(f"Transform my photo into a sophisticated {v['Mood'].lower()} portrait. {identity}"
                f"Give me a {v['Expression'].lower()} with relaxed, confident posture and natural emotional expression. "
                f"Use {v['Lighting'].lower()} to create dimensional, flattering illumination with realistic highlights, soft shadow transitions, subtle rim light, and natural catchlights. "
                f"Place me in {v['Environment'].lower()}, creating an elegant sense of depth and atmosphere. "
                f"Style the portrait with {v['Styling'].lower()}, keeping clothing, hair, accessories, and grooming refined and believable. "
                f"Photograph the scene as a {v['Composition'].lower()} using a {v['Camera'].lower()}, with a {v['Angle'].lower()} perspective and {v['Depth'].lower()}. "
                f"The emotional direction should communicate {intensity}. {detail}"
                f"Use cinematic composition, natural color grading, realistic facial detail, subtle background separation, professional editorial photography, and premium photographic depth. "
                f"The result should feel romantic, mysterious, confident, intimate, sophisticated, and subtly alluring, with tasteful sensuality conveyed through expression, atmosphere, styling, and lighting rather than explicit content.")
        self.result.setPlainText(prompt)

    def surprise_me(self):
        for c in self.controls.values(): c.setCurrentIndex(random.randrange(c.count()))
        self.intensity.setValue(random.randint(1,4)); self.build_prompt()

    def refresh_library(self):
        q=self.search.text().lower().strip(); cat=self.category.currentText(); self.list.blockSignals(True); self.list.clear(); self.filtered=[]
        for p in PROMPTS:
            if q and q not in (p["title"]+" "+p["category"]+" "+p["prompt"]).lower(): continue
            if cat!="All categories" and p["category"]!=cat: continue
            if self.fav_only.isChecked() and p["id"] not in self.favorites: continue
            self.filtered.append(p); star=" ♥" if p["id"] in self.favorites else ""; self.list.addItem(QListWidgetItem(f'{p["id"]:03d}  {p["category"]}{star}'))
        self.list.blockSignals(False)
        if self.filtered and self.list.currentRow()<0: self.list.setCurrentRow(0)
        self.statusBar().showMessage(f"{len(self.filtered)} prompts shown • 100 total")

    def select_library(self,row):
        if 0<=row<len(self.filtered):
            p=self.filtered[row]; self.current_prompt_id=p["id"]; self.library_title.setText(f'{p["id"]:03d} — {p["category"]}'); self.library_meta.setText(f'{p["category"]} • Detailed Prompt {p["id"]} of 100'); self.library_editor.setPlainText(p["prompt"])

    def toggle_favorite(self):
        if self.current_prompt_id is not None:
            self.favorites.symmetric_difference_update({self.current_prompt_id}); self.refresh_library()

    def random_library(self):
        if self.filtered: self.list.setCurrentRow(random.randrange(len(self.filtered)))

    def use_library_in_workspace(self):
        if self.library_editor.toPlainText(): self.result.setPlainText(self.library_editor.toPlainText()); self.statusBar().showMessage("Library prompt loaded",1500)

    def copy_text(self,text):
        if text.strip(): QApplication.clipboard().setText(text); self.statusBar().showMessage("Copied to clipboard",1500)
    def copy_result(self): self.copy_text(self.result.toPlainText())
    def copy_all(self): self.copy_text(self.result.toPlainText().strip()+"\n\nNEGATIVE PROMPT\n"+self.negative.toPlainText().strip())

    def load_history(self):
        try: return json.loads(DATA_FILE.read_text(encoding="utf-8")) if DATA_FILE.exists() else []
        except Exception: return []

    def persist_history(self):
        try: DATA_FILE.write_text(json.dumps(self.history,ensure_ascii=False,indent=2),encoding="utf-8")
        except Exception: pass

    def save_history(self):
        if self.result.toPlainText().strip():
            self.history.insert(0,{"prompt":self.result.toPlainText().strip(),"negative":self.negative.toPlainText().strip(),"mood":self.controls["Mood"].currentText(),"photo":self.photo_path})
            self.history=self.history[:100]; self.persist_history(); self.refresh_history(); self.statusBar().showMessage("Saved to local history",1500)

    def refresh_history(self):
        if hasattr(self,"history_list"):
            self.history_list.clear()
            for i,x in enumerate(self.history): self.history_list.addItem(f'{i+1:03d}  {x.get("mood","Generated")} — {x.get("prompt","").replace(chr(10)," ")[:105]}')

    def load_selected_history(self):
        r=self.history_list.currentRow()
        if 0<=r<len(self.history):
            x=self.history[r]; self.result.setPlainText(x.get("prompt","")); self.negative.setPlainText(x.get("negative",NEGATIVE_BASE))
            photo=x.get("photo","")
            if photo and Path(photo).exists(): self.photo_path=photo; self.photo_preview.set_photo(photo); self.photo_info.setText(Path(photo).name)
            self.statusBar().showMessage("History item loaded",1500)

    def delete_history(self):
        r=self.history_list.currentRow()
        if 0<=r<len(self.history): self.history.pop(r); self.persist_history(); self.refresh_history()

    def clear_history(self): self.history=[]; self.persist_history(); self.refresh_history()

    def export_txt(self):
        path,_=QFileDialog.getSaveFileName(self,"Export Prompt","portrait_prompt.txt","Text files (*.txt)")
        if path:
            Path(path).write_text("JASS PORTRAIT PROMPT STUDIO\n\nPROMPT\n=======\n"+self.result.toPlainText().strip()+"\n\nNEGATIVE PROMPT\n===============\n"+self.negative.toPlainText().strip()+"\n",encoding="utf-8")
            self.statusBar().showMessage("Prompt exported",1500)

def main():
    app=QApplication(sys.argv); app.setApplicationName(APP_NAME); app.setStyle("Fusion"); w=PromptStudio(); w.show(); sys.exit(app.exec())

if __name__=="__main__": main()
